import { insightText } from './insight-format.js';
import { privateJson } from './session.js';
if(!document.querySelector('link[href="/coaching.css"]')){const css=document.createElement('link');css.rel='stylesheet';css.href='/coaching.css';document.head.append(css);}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function formatFact(f){const v=f?.value;if(!Number.isFinite(v))return 'Unavailable';if(f.unit==='s/km'){const n=Math.round(Math.abs(v));return (v<0?'−':'')+Math.floor(n/60)+':'+String(n%60).padStart(2,'0')+' /km';}if(f.unit==='m')return new Intl.NumberFormat('en-AU',{maximumFractionDigits:2}).format(v/1000)+' km';if(f.unit==='s'){const n=Math.round(v);return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');}return new Intl.NumberFormat('en-AU',{maximumFractionDigits:1}).format(v)+(f.unit==='count'?'':f.unit==='bpm'?' bpm':f.unit==='spm'?' spm':f.unit==='/10'?' /10':' '+f.unit);}
export function coachingContent(review){
 if(!review||review.stale)return '';
 const facts=new Map(review.evidence.facts.map(f=>[f.id,f])),prose=text=>esc(insightText(text,review.evidence.facts,formatFact)),verdict=review.report.verdict;
 const proof=ids=>`<dl class="ai-proof">${ids.slice(0,3).map(id=>`<div><dt>${esc(facts.get(id)?.label)}</dt><dd>${esc(formatFact(facts.get(id)))}</dd></div>`).join('')}</dl>`;
 return `<div class="ai-verdict"><h3>${prose(review.report.verdict.text)}</h3><p class="ai-explanation">${prose(verdict.explanation)}</p><div class="ai-next"><h4>For your next run</h4><p>${prose(verdict.nextAction)}</p></div></div>${review.report.findings.length?`<details class="ai-more"><summary>${review.report.findings.length} more ${review.report.findings.length===1?'finding':'findings'}</summary>${review.report.findings.map(f=>`<article><h4>${prose(f.headline)}</h4><p>${prose(f.explanation)}</p><p class="ai-action-line">${prose(f.nextAction)}</p></article>`).join('')}</details>`:''}<details class="ai-evidence"><summary>See the numbers</summary>${proof(verdict.factIds)}<div class="ai-source-links">${[...new Set([...verdict.factIds,...review.report.findings.flatMap(f=>f.factIds)].flatMap(id=>facts.get(id)?.sessionIds||[]))].slice(0,4).map((ref,i)=>`<a href="/app.html?activity=${encodeURIComponent(review.mapping[ref])}">View cited run ${i+1}</a>`).join('')}</div>${review.report.charts.map(c=>`<div class="ai-comparison"><h4>${{pace:'Pace comparison',distance:'Distance comparison',heart_rate:'Heart-rate comparison'}[c.type]}</h4><table><caption class="sr-only">Recorded values for the cited runs</caption><thead><tr><th scope="col">Run</th><th scope="col">Value</th></tr></thead><tbody>${c.sessionIds.map(ref=>{const f=facts.get(ref+'.'+{pace:'paceSPerKm',distance:'distanceM',heart_rate:'hrBpm'}[c.type]);return `<tr><th scope="row"><a href="/app.html?activity=${encodeURIComponent(review.mapping[ref])}">${formatFact(facts.get(ref+'.distanceM'))}</a></th><td>${esc(formatFact(f))}</td></tr>`;}).join('')}</tbody></table></div>`).join('')}<p class="ai-fine">Updated ${new Date(review.generatedAt).toLocaleDateString('en-AU')} · ${esc(review.model)} · high thinking</p></details>`;
}
export async function mountCoaching(root,{settings=false}={}){
 root.classList.add('ai-space');root.id=settings?'ai-settings':'coaching';root.innerHTML='<p role="status">Opening your coaching brief…</p>';
 let state,busy=false,message='',destroyed=false,request=0;
 const notice=()=>`<details class="ai-sharing"><summary>What is shared with Gemini?</summary><p>Run summaries, splits, heart-rate/cadence summaries and structured check-ins. Names, email, GPS routes, screenshots, free-text notes and credentials stay out.</p><p>Google’s free service may use requests to improve its products, including human review. Its unpaid-service terms restrict personal or sensitive submissions; your app permission does not change those terms. <a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noopener noreferrer">Google’s data terms</a>.</p><p>Switching off stops new requests and hides saved briefings. Requests already sent cannot be recalled.</p></details>`;
 function render(){if(destroyed||!root.isConnected)return;const consent=state?.consent||{},enabled=consent.enabled===true,unanswered=consent.enabled==null,review=state?.review,needsRuns=Number.isFinite(state?.runs)&&state.runs<2;
 root.innerHTML=`<div class="ai-header"><h2>${settings?'Your AI preferences':'Your coaching brief'}</h2><span class="ai-status">${enabled?'Gemini':'AI off'}</span></div>
 ${!enabled||settings?`<div class="ai-consent"><h3>${settings?'You choose what gets analysed.':unanswered?'Turn your runs into a clear next step.':'Your runs are ready when you are.'}</h3><p>${enabled?'Gemini reviews your running history only when you ask.':unanswered?'Let Gemini connect your pace, effort and consistency, then suggest what to do next.':'Your charts and logging stay available with AI off.'}</p>${notice()}<div class="ai-actions">${enabled?'<button class="secondary-button" data-ai="deny">Turn AI off</button>':`<button class="primary-button" data-ai="allow">Allow run analysis</button>${unanswered?'<button class="text-button" data-ai="deny">Not now</button>':''}`}</div></div>`:''}
 ${enabled&&!settings?(review&&!review.stale?coachingContent(review):`<div class="ai-ready"><h3>${needsRuns?'Your next run unlocks a bigger picture.':review?'Your latest runs need a fresh look.':'Find the next move in your training.'}</h3><p>${needsRuns?'Add two runs to compare your pace, effort and consistency.':review?'Update your brief to bring your latest sessions into the picture.':'Get a clear finding, the numbers behind it and one useful action for your next run.'}</p></div>`):''}
 ${enabled&&!settings?`<div class="ai-actions">${needsRuns?'<a class="primary-button" href="/account">Add a run</a>':!review||review.stale?`<button class="primary-button" data-ai="generate" ${busy||!state.configured?'disabled':''}>${busy?'Reading your training…':review?'Update my brief':'Review my runs'}</button>`:''}<a class="text-button" href="/account#ai-settings">AI settings</a></div>${!state.configured?'<p class="ai-fine">Gemini is unavailable here. Your training stays ready to explore.</p>':''}${review?.stale?`<details class="ai-previous"><summary>Previous brief · ${new Date(review.generatedAt).toLocaleDateString('en-AU')}</summary><p>${esc(review.report.verdict.text).replace(/\{([\w.]+)\}/g,(_,id)=>esc(formatFact(review.evidence.facts.find(f=>f.id===id))))}</p></details>`:''}`:''}
 <p class="ai-message" role="status" aria-live="polite">${esc(message)}</p>`;
 root.querySelectorAll('[data-ai]').forEach(b=>{b.disabled=busy||(b.dataset.ai==='generate'&&!state.configured);b.addEventListener('click',()=>act(b.dataset.ai));});
 }
 async function load(){const token=++request,next=await privateJson('/api/private?route=ai-review');if(token===request){state=next;render();}}
 async function act(action){if(busy)return;busy=true;message=action==='generate'?'Comparing your runs. You can keep exploring while your brief is prepared.':'Saving your choice…';render();try{if(action==='generate'){state.review=await privateJson('/api/private?route=ai-review',{method:'POST'});message='Your coaching brief is ready.';}else{const consent=await privateJson('/api/private?route=ai-consent',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:action==='allow'})});state={...state,consent,review:null};try{localStorage.setItem('mfa-ai-preference-changed',String(Date.now()));}catch{}message=consent.enabled?'Analysis is enabled. Request your brief when ready.':'AI is off.';await load();}}catch(e){message=e.message;}finally{busy=false;render();root.querySelector('.ai-message')?.setAttribute('tabindex','-1');root.querySelector('.ai-message')?.focus({preventScroll:true});}}
 const changed=event=>{if(event.key==='mfa-ai-preference-changed')void load().catch(e=>{root.textContent=e.message;});};addEventListener('storage',changed);addEventListener('pagehide',()=>{destroyed=true;removeEventListener('storage',changed);},{once:true});
 try{await load();}catch(e){root.innerHTML=`<h2>Your coaching brief</h2><p role="status">${esc(e.message)}</p><button class="text-button" id="retry-coach">Try again</button>`;root.querySelector('#retry-coach').addEventListener('click',()=>void load().catch(e=>root.querySelector('[role=status]').textContent=e.message));}
}
